<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { SORT_OPTIONS, sortDeviationRows, filterDeviationRows, overSixty, distanceText, nearLineText, tomorrowText, dangerDistance, benchmarkText, updateText, numberText, percent } from './deviationLogic.js'

const meta = ref({ dates: [], days: [] }), report = ref(null), date = ref(''), tab = ref('scan'), sort = ref('effective_remain')
const filters = reactive({ onlySixty: false, query: '' }), expandedOver = ref(false), loading = ref(true), refreshing = ref(false)
const error = ref(''), message = ref(''), authOpen = ref(false), token = ref('')
try { token.value = sessionStorage.getItem('monitor-token') || '' } catch { /* Keep this page usable when storage is disabled. */ }
let controller, refreshController, timer, sequence = 0, stopped = false, followDefault = true
const summary = computed(() => report.value?.summary || {})
const benchmarks = computed(() => summary.value.benchmarks || meta.value.benchmarks || [])
const selectedDay = computed(() => (meta.value.days || []).find(day => day.date === date.value))
const rows = computed(() => sortDeviationRows(filterDeviationRows(report.value?.items || [], filters), sort.value))
const tierSpec = [
  { key: 'A', name: '一步之内', note: '还差不到 16%，具体看明日涨停测算。' },
  { key: 'B', name: '半山腰', note: '还差 16%–32%，仍需观察承接与窗口变化。' },
  { key: 'C', name: '仍有余量', note: '还差 32%–55%，不作连续涨停板数承诺。' },
]
const tiers = computed(() => tierSpec.map(tier => ({ ...tier, items: sortDeviationRows(filterDeviationRows(report.value?.risk_ladder?.[tier.key] || [], filters), sort.value) })))
const overRows = computed(() => sortDeviationRows(filterDeviationRows(report.value?.risk_ladder?.over_55_items || [], filters), sort.value))
const nearRows = computed(() => sortDeviationRows(filterDeviationRows(report.value?.near_trigger_top || [], filters), sort.value))
const stateText = value => ({ ready: '已就绪', complete: '已完成', partial: '部分数据可用', pending: '后台补算中', scheduled: '等待盘后结算', unavailable: '暂不可用', calendar_unavailable: '交易日历尚未就绪', queued: '排队中' })[value] || value || '--'
async function request(path, signal, options = {}) {
  const response = await fetch(path, { ...options, signal, headers: { 'Content-Type': 'application/json', ...(token.value ? { Authorization: `Bearer ${token.value}` } : {}) } })
  const result = await response.json()
  if (!response.ok) throw new Error(response.status === 401 ? '令牌无效，请展开连接设置' : typeof result.detail === 'string' ? result.detail : `请求失败（HTTP ${response.status}）`)
  return result
}
async function load() {
  clearTimeout(timer); controller?.abort()
  const current = ++sequence, active = new AbortController(); controller = active
  const timeout = setTimeout(() => active.abort(), 10000)
  loading.value = !report.value; error.value = ''
  try {
    const nextMeta = await request('/api/deviation/meta', active.signal)
    if (stopped || current !== sequence) return
    meta.value = nextMeta
    if (nextMeta.dates?.length && !nextMeta.dates.includes(date.value)) followDefault = true
    if (!date.value || followDefault) date.value = nextMeta.default_date || nextMeta.dates?.[0] || ''
    if (report.value?.date !== date.value) { report.value = null; loading.value = true }
    if (!date.value) { message.value = '交易日历尚未就绪，后台将自动重试'; return }
    const data = await request(`/api/deviation/report?date=${encodeURIComponent(date.value)}`, active.signal)
    if (stopped || current !== sequence) return
    report.value = data
    if (message.value === '交易日历尚未就绪，后台将自动重试') message.value = ''
  } catch (failure) {
    if (!stopped && current === sequence) error.value = failure.name === 'AbortError' ? '读取缓存超时，稍后自动重试' : failure.message
  } finally {
    clearTimeout(timeout)
    if (!stopped && current === sequence) { loading.value = false; timer = setTimeout(load, 30000) }
  }
}
function chooseDate() { followDefault = date.value === meta.value.default_date; report.value = null; expandedOver.value = false; void load() }
function saveToken() {
  try { if (token.value) sessionStorage.setItem('monitor-token', token.value); else sessionStorage.removeItem('monitor-token') } catch { /* Requests still carry the in-memory token. */ }
  void load()
}
async function refresh() {
  if (refreshing.value || !date.value) return
  refreshing.value = true; message.value = ''; refreshController = new AbortController()
  const timeout = setTimeout(() => refreshController.abort(), 10000)
  try {
    await request('/api/deviation/refresh', refreshController.signal, { method: 'POST', body: JSON.stringify({ date: date.value }) })
    message.value = '重新结算已排队，后台完成后自动读取归档'; void load()
  } catch (failure) { if (!stopped) message.value = failure.name === 'AbortError' ? '提交超时，请稍后重试' : failure.message }
  finally { clearTimeout(timeout); refreshing.value = false }
}
onMounted(load)
onBeforeUnmount(() => { stopped = true; sequence++; clearTimeout(timer); controller?.abort(); refreshController?.abort() })
</script>

<template>
  <div class="terminal deviation-page">
    <header class="deviation-console">
      <nav class="deviation-navigation" aria-label="页面导航"><a href="#/">← 返回实时盯盘</a><a href="#/review">涨停梯队复盘</a><span class="deviation-kicker">MAIN BOARD / REGULATORY THRESHOLD</span><button class="deviation-link" :aria-expanded="authOpen" @click="authOpen = !authOpen">连接设置</button></nav>
      <div class="deviation-heading"><div><h1>纯主板严重异动监控</h1><p>10 日 +100% / 30 日 +200% · 纯盘后情景测算</p></div><span class="deviation-model-badge">{{ meta.simulated ? '模拟演练 MOCK' : '情景测算 · 非监管认定' }}</span></div>
      <div class="deviation-controlbar"><div class="deviation-view-tabs" role="group" aria-label="红线视图"><button :aria-pressed="tab === 'scan'" :class="{ selected: tab === 'scan' }" @click="tab = 'scan'">监控池全景（主页）</button><button :aria-pressed="tab === 'ladder'" :class="{ selected: tab === 'ladder' }" @click="tab = 'ladder'">分档看危险度（副页）</button></div><label>结算日期<select v-model="date" @change="chooseDate"><option v-if="!meta.dates?.length" value="">等待交易日历</option><option v-for="day in meta.dates" :key="day" :value="day">{{ day }}{{ day === meta.default_date ? ' · 当前锁定' : '' }}</option></select></label><button class="deviation-refresh" :disabled="refreshing || !date || meta.refresh_allowed === false" @click="refresh">{{ refreshing ? '正在提交…' : '手动重新结算' }}</button></div>
      <p class="deviation-lock">盘后结算 · 保持至下一交易日15:00 <span>{{ summary.locked_until_text || meta.locked_until_text || meta.next_refresh_text }}</span></p>
      <form v-if="authOpen" class="deviation-auth" @submit.prevent="saveToken"><label for="deviation-token">API 令牌</label><input id="deviation-token" v-model="token" type="password" autocomplete="off"><button class="deviation-refresh">保存并连接</button></form>
    </header>

    <p v-if="meta.simulated" class="deviation-notice">模拟数据用于离线验收，不代表真实行情或监管结论。</p>
    <p v-if="error" class="deviation-notice deviation-error" role="alert">{{ error }}<span v-if="report"> · 保留最近成功归档</span><button class="deviation-link" @click="load">重试读取</button></p>
    <p v-if="message" class="deviation-notice" role="status">{{ message }}</p>
    <p v-if="selectedDay?.error" class="deviation-notice" role="status">{{ selectedDay.error }}</p>
    <p v-if="summary.coverage?.truncated_count || summary.failed_count" class="deviation-notice">初筛候选 {{ numberText(summary.candidate_count, 0) }} 只；{{ numberText(summary.failed_count, 0) }} 只指标不足。<span v-if="summary.coverage?.truncated_count">受初筛上限影响，另有 {{ summary.coverage.truncated_count }} 只尚未覆盖。</span></p>
    <p v-if="report?.error || report?.status && !['ready', 'complete'].includes(report.status)" class="deviation-notice" role="status">{{ report.error || stateText(report.status) }}</p>
    <div class="deviation-benchmarks"><span v-for="benchmark in benchmarks" :key="benchmark.market || benchmark.code" :class="{ 'deviation-fallback': benchmark.fallback }">{{ benchmark.market === 'sh' ? '沪市' : benchmark.market === 'sz' ? '深市' : benchmark.market }}：{{ benchmarkText(benchmark) }}<small v-if="benchmark.status && benchmark.status !== 'ready'"> · {{ stateText(benchmark.status) }}</small></span><span>更新 {{ updateText(summary.updated_at) }}</span></div>

    <section class="deviation-titlebar"><div><span class="deviation-kicker">{{ summary.date || date || '--' }} {{ summary.weekday || '--' }} / {{ tab === 'scan' ? 'FULL SCAN' : 'RISK LADDER' }}</span><h2>{{ tab === 'scan' ? '监控池全景' : '分档看危险度' }}</h2><p v-if="tab === 'scan'" class="deviation-subtitle"><strong>{{ numberText(summary.total_candidates, 0) }}</strong> 只异动候选里，<strong class="deviation-gold">{{ numberText(summary.over_60_count, 0) }}</strong> 只偏离值已经越过 60%</p><p v-else class="deviation-subtitle">同样在涨，离红线的距离差着好几个板</p></div><button v-if="tab === 'ladder'" class="deviation-refresh" @click="tab = 'scan'">← 监控池全景</button></section>

    <div class="deviation-tools"><label>排序<select v-model="sort"><option v-for="option in SORT_OPTIONS" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><label class="deviation-checkbox"><input v-model="filters.onlySixty" type="checkbox">仅看 ≥60%</label><label class="deviation-search">代码 / 名称<input v-model="filters.query" type="search" maxlength="32" placeholder="搜索股票"></label><span>筛选后 {{ rows.length }} 只</span><button v-if="tab === 'scan'" class="deviation-ladder-link" @click="tab = 'ladder'">分档看危险度 →</button></div>
    <p v-if="loading" class="deviation-empty" role="status">正在读取盘后归档…</p>
    <template v-else-if="report">
      <section v-if="tab === 'scan'" class="deviation-table-panel" aria-label="监控池全景列表">
        <div class="deviation-table-scroll" tabindex="0" aria-label="监控池表格，可滚动"><table class="deviation-table"><thead><tr><th scope="col">NO</th><th scope="col">个股</th><th scope="col">10 日偏离</th><th scope="col">30 日偏离</th><th scope="col">离 100%</th><th scope="col">离 200%</th></tr></thead><tbody><tr v-for="(row, index) in rows" :key="row.code" :class="{ 'over-sixty': overSixty(row), 'already-triggered': row.already_triggered }"><td class="deviation-rank">{{ String(index + 1).padStart(2, '0') }}</td><td class="deviation-stock"><b>{{ row.name }}</b><span>{{ row.code }}</span><small v-if="row.already_triggered" class="deviation-triggered">测算已越线</small><small v-else-if="row.data_status && row.data_status !== 'ready'" class="deviation-missing">{{ stateText(row.data_status) }}</small></td><td :class="{ 'deviation-gold': overSixty(row) }">{{ percent(row.dev_10, true) }}</td><td>{{ percent(row.dev_30, true) }}</td><td :class="{ 'deviation-danger': dangerDistance(row.remain_10) || row.already_triggered }">{{ distanceText(row.remain_10) }}</td><td :class="{ 'deviation-danger': dangerDistance(row.remain_30) || row.already_triggered }">{{ distanceText(row.remain_30) }} <span v-if="nearLineText(row)" class="deviation-near">{{ nearLineText(row) }}</span></td></tr></tbody></table><p v-if="!rows.length" class="deviation-empty">{{ report.status === 'ready' ? '暂无符合当前筛选的异动候选' : '暂无可用数据，后台将继续补算' }}</p></div>
      </section>
      <div v-else class="deviation-ladder-view">
        <section class="deviation-risk-grid" aria-label="A B C 危险度分档"><article v-for="tier in tiers" :key="tier.key" class="deviation-risk-tier" :class="`deviation-tier-${tier.key}`"><header><div><h3>{{ tier.key }} 档 · {{ tier.name }}</h3><p>{{ tier.note }}</p></div><b>{{ tier.items.length }}<small>只</small></b></header><div class="deviation-pill-scroll" tabindex="0" :aria-label="`${tier.key}档候选，可滚动`"><div class="deviation-pills"><span v-for="row in tier.items" :key="row.code" class="deviation-pill" :title="`${row.code} · 离10日线 ${distanceText(row.remain_10)} / 离30日线 ${distanceText(row.remain_30)}`"><b>{{ row.name }}</b><strong>{{ distanceText(row.effective_remain, true) }}</strong><small v-if="row.near_line_30">30日近线</small><small v-if="row.already_triggered">已越线</small></span><span v-if="!tier.items.length" class="deviation-muted">暂无符合筛选的股票</span><button v-if="tier.key === 'C' && overRows.length" class="deviation-over-toggle" :aria-expanded="expandedOver" aria-controls="deviation-over-55" @click="expandedOver = !expandedOver">{{ expandedOver ? '收起' : '另' }} {{ overRows.length }} 只 &gt; 55% {{ expandedOver ? '−' : '+' }}</button></div><div v-if="tier.key === 'C' && expandedOver" id="deviation-over-55" class="deviation-pills deviation-over-pills"><span v-for="row in overRows" :key="row.code" class="deviation-pill"><b>{{ row.name }}</b><strong>{{ distanceText(row.effective_remain, true) }}</strong><small v-if="row.near_line_30">30日近线</small></span></div></div></article></section>
        <p v-if="summary.tier_counts?.unknown" class="deviation-notice">另有 {{ numberText(summary.tier_counts.unknown, 0) }} 只指标不足，保留在全景表中，不以零值分档。</p>
        <section class="deviation-table-panel deviation-near-panel"><h3>再涨几个点，就越线 <small>明日指数涨跌假设 0%，主板涨停统一 +10%</small></h3><div class="deviation-table-scroll" tabindex="0" aria-label="明日涨停测算，可滚动"><table class="deviation-table"><thead><tr><th scope="col">个股</th><th scope="col">10 日偏离</th><th scope="col">还需上涨</th><th scope="col">明日涨停 (+10%)</th></tr></thead><tbody><tr v-for="row in nearRows" :key="row.code"><td class="deviation-stock"><b>{{ row.name }}</b><span>{{ row.code }}</span></td><td>{{ percent(row.dev_10, true) }}</td><td class="deviation-danger">{{ distanceText(row.effective_remain) }} <span v-if="row.near_line_30" class="deviation-near">30日近线</span></td><td :class="{ 'deviation-danger': row.tomorrow_cross === true }">{{ tomorrowText(row) }}</td></tr></tbody></table><p v-if="!nearRows.length" class="deviation-empty">暂无符合筛选的近线候选</p></div></section>
        <section class="deviation-guidance" aria-label="分档怎么用"><h3>分档怎么用 <small>情景提示，非买卖指令</small></h3><div><article><h4>A 档 · 别接力</h4><p>阈值只作追涨风险警示；核查、披露及指标重置以正式公告为准。</p></article><article><h4>B 档 · 看承接</h4><p>观察放量换手与承接，缩量加速不代表风险已经解除。</p></article><article><h4>C 档 · 看主线</h4><p>结合板块与公告观察；仍有余量不代表安全或上涨空间。</p></article></div><p class="deviation-tier-counts">A档 {{ numberText(summary.tier_counts?.A, 0) }} 只 · B档 {{ numberText(summary.tier_counts?.B, 0) }} 只 · C档 {{ numberText(summary.tier_counts?.C, 0) }} 只</p></section>
      </div>
    </template>
    <p v-else class="deviation-empty">暂无盘后归档，后台补齐后自动显示。</p>

    <footer class="deviation-method"><p>口径：偏离值 = 个股区间涨幅 − 对应指数区间涨幅；窗口 {{ summary.window_10_range || '--' }} / {{ summary.window_30_range || '--' }}；「近线」= 该股对30日200%红线的距离更短；红线：10日 +100% / 30日 +200%。</p><p>{{ summary.calculation_note || '剩余涨幅采用复利与明日合法滑动窗口求最紧值，并非100%减去当前偏离值。仅使用收盘归档，不做盘中计算或推送。' }}</p><details><summary>测算局限与官方口径</summary><ul><li v-for="note in summary.limitations || ['未自动识别公告或复牌后的监管指标重置、无价格限制日；结果属于情景测算，不能代替正式监管认定。', '明日指数假设不变，指数替代、缺失行情和窗口滚动可能影响结果。']" :key="note">{{ note }}</li></ul><p><a href="https://www.sse.com.cn/lawandrules/sselawsrules2025/stocks/exchange/c/c_20260424_10816482.shtml" target="_blank" rel="noopener noreferrer">上交所交易规则</a> · <a href="https://docs.static.szse.cn/www/lawrules/rule/trade/W020260424690713155663.pdf" target="_blank" rel="noopener noreferrer">深交所交易规则</a></p></details></footer>
  </div>
</template>

<style scoped>
